OPTIONAL MATCH p=(s:PlantItem {tag: "T-1201"})-[:send_to*1..]->(t:PlantItem {tag: "TK-1303"})
WHERE all(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> "P-1202B")
RETURN count(p) > 0 AS can_flow, collect([n IN nodes(p) | n.tag]) AS path_tags;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'E-403'})
WHERE NOT EXISTS { MATCH (:PlantItem)-[:send_to]->(source) }
RETURN DISTINCT source.tag AS tag

MATCH (start:PlantItem {tag: 'TK-58301'})-[:send_to*1..]->(downstream:PlantItem)-[:is_located_in]->(section:PlantSection)
WHERE section.unit_id <> start.unit_id
RETURN count(DISTINCT section.unit_id) AS other_unit_count;

MATCH (start:PlantItem {tag: "P-11201A"}), (target:PlantItem {tag: "V-12401"})
RETURN start.tag AS source_tag, target.tag AS target_tag,
       EXISTS { MATCH (start)-[:send_to*1..]->(target) } AS process_flow_can_reach_target;

MATCH (s:PlantItem {tag: "P-41701"}), (t:PlantItem {tag: "K-43101"})
RETURN s.tag AS source_tag, t.tag AS destination_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*0..]->(t)
         WHERE ALL(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> "YV-424026")
       } AS can_flow_without_valve

